That's the one and only place, and I thoroughly regret it.  It would have been generally more sane to pass an OSSL_PARAM array.

The whole idea with OSSL_PARAM arrays was to allow extensible optional parametrization and avoid having to change the API for such things.

issue_context.body:
I'm building 3.0.7 with enable-fips and attempting to use a FIPS configuration as the default via a config file.

The code is attempting to load a private key file encrypted using 'pbeWithSHA1And3-KeyTripleDES-CBC', generated by "openssl genrsa -des3". This requires relaxing the FIPS mode and allowing non-FIPS algorithms for the decrypt. I've tried the following property queries:

  ```
  "?fips=yes"
  "-fips"
  "?provider=default"
  ```

None of these seem to have any effect.

Alternatively if I run with a non-FIPS configuration file and use "fips=yes" as property query the decode succeeds, which it probably shouldn't!

My repro code is:

```
#include <stdio.h>
#include <string.h>

#include <openssl/bio.h>
#include <openssl/pem.h>
#include <openssl/core_names.h>
#include <openssl/err.h>
#include <openssl/provider.h>

#define KEY_FILE         "key.pem"
#define PASSWORD_FILE    "pass"
#define PROVIDER_PATH    "openssl-3.0.7/providers"

static EVP_PKEY *privkey = NULL;

int OpenSsl_configure(char* modules_path, char* config_file)
{
    int ret;

    if (modules_path == NULL || config_file == NULL)
        goto err;

    ret = OSSL_PROVIDER_set_default_search_path(NULL, modules_path);
    if (!ret)
        goto err;

    ret = OSSL_LIB_CTX_load_config(NULL, config_file);
    if (!ret)
        goto err;

    if (!EVP_default_properties_is_fips_enabled(NULL)) {
        printf("WARNING: FIPS is not enabled\n");
    } else {
        printf("INFO: FIPS is enabled\n");
    } 

    if (!OSSL_PROVIDER_available(NULL, "fips")) {
        printf("WARNING: Failed to retrieve fips provider\n");
    }   

    printf("Successfully configured OpenSSL\n");
    return 1;
err:
    return 0;
}

static pem_password_cb pass_pw;
static int pass_pw(char *buf, int size, int rwflag, void *userdata)
{
    int read;
    BIO * pb = BIO_new_file(PASSWORD_FILE, "rb");

    read = BIO_read(pb, buf, size);
    buf[read] = 0;
    return read-1;
}

int main(int argc, char *argv[])
{
    BIO *bio_out = BIO_new_fp(stdout, BIO_NOCLOSE);
    char *privkeyin = KEY_FILE;
    BIO  *privkeybio = NULL;

    printf("Using config file %s\n", argv[1]);
    if (!OpenSsl_configure(PROVIDER_PATH, argv[1])) {
        printf("ERROR: Failed to configure OpenSSL\n");
        goto err;
    }

    privkeybio = BIO_new_file(privkeyin, "r");
    if (!privkeybio) {
        printf("ERROR: Failed to create bio\n");
        goto err;
    }

    char *propq = "?fips=yes"; 
    printf("Decoding private key with property string '%s'\n", propq);
    if (!PEM_read_bio_PrivateKey_ex(privkeybio, &privkey, &pass_pw, NULL, NULL, propq)) {
        printf("ERROR: Failed to read private key\n");
        BIO_free(privkeybio);
        goto err;
    }

    BIO_free(privkeybio);
    printf("Success!\n");
    return 0;
err:
    ERR_print_errors(bio_out);
    return 1;
}
```

