To reproduce this problem you can use the script:

```#!/bin/bash
#
# Test the pem decoder in fips mode
#

export OPENSSL_DIR="../"
export OPENSSL_MODULES="$OPENSSL_DIR/providers"

set -e

echo "Creating conf files"

echo '''
openssl_conf = openssl_init

config_diagnostics = 1
''' > template.cnf

cat $OPENSSL_MODULES/fipsmodule.cnf >> template.cnf

echo '''
[openssl_init]
providers = provider_sect
alg_section = algorithm_sect

[provider_sect]
default = default_sect
fips = fips_sect

[default_sect]
activate = 1

[algorithm_sect]
''' >> template.cnf

# Create three configs for the tests
cp template.cnf osl-nonfips.cnf
echo "default_properties = " >> osl-nonfips.cnf
cp template.cnf osl-strictfips.cnf
echo "default_properties = fips=yes" >> osl-strictfips.cnf
cp template.cnf osl-preferredfips.cnf
echo "default_properties = ?fips=yes" >> osl-preferredfips.cnf

echo "Generating key"

echo "password" > pass
openssl genrsa -des3 -passout file:pass -out key.pem

echo "Reading key (default)"
openssl pkey -in key.pem -passin file:pass -noout -text

echo "Building test app"
gcc -I $OPENSSL_DIR/include -L $OPENSSL_DIR -lcrypto pkey_read.c -o pkey_read

set +e
echo "Running test app"

LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-nonfips.cnf ""
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-nonfips.cnf "-fips"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-nonfips.cnf "?fips=yes"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-nonfips.cnf "fips=yes"

LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-preferredfips.cnf ""
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-preferredfips.cnf "-fips"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-preferredfips.cnf "?fips=yes"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-preferredfips.cnf "fips=yes"

LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-strictfips.cnf ""
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-strictfips.cnf "-fips"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-strictfips.cnf "?fips=yes"
LD_LIBRARY_PATH=$OPENSSL_DIR ./pkey_read osl-strictfips.cnf "fips=yes"

echo "Done"
```

