    if (argc != 3) {
        printf("ERROR: Please supply a config file and query string\n");
        goto err;
    }

    printf("Using config file %s\n", argv[1]);
    if (!OpenSsl_configure(argv[1])) {
        printf("ERROR: Failed to configure OpenSSL\n");
        goto err;
    }

    privkeybio = BIO_new_file(privkeyin, "r");
    if (!privkeybio) {
        printf("ERROR: Failed to create bio\n");
        goto err;
    }

    char *propq = argv[2];
    printf("Decoding private key with property string '%s'\n", propq);
    if (!PEM_read_bio_PrivateKey_ex(privkeybio, &privkey, &pass_pw, NULL, NULL, propq)) {
